"""
מקור התוכן של חלק ב (המשך הגמרא: כ"ג ע"ב אחרי מחרוזות של דגים, וכל דף כ"ד ע"א).
מייצר את data/part_b.json.  הרצה:  python3 tools/part_b_source.py
* טקסט הגמרא המנוקד נלקח מילה במילה מ-tools/sefaria/bm_23b_24a.json (ספריא, William Davidson).
  הסקריפט בודק שחיבור כל השורות שווה בדיוק לטקסט של ספריא – כך שאין ניקוד מומצא.
* התרגומים וההסברים מבוססים על שטיינזלץ ורש"י (שמורים באותו קובץ).
"""
import json, os, re, sys, unicodedata
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
SRC = json.load(open(os.path.join(ROOT, 'tools/sefaria/bm_23b_24a.json'), encoding='utf-8'))
PUNCT = re.compile(r'[\u0591-\u05C7.,:;!?–״׳"\'()\[\]]')
def strip(s): return PUNCT.sub('', unicodedata.normalize('NFC', s)).strip().replace('יי','י').replace('וו','ו')

