  ('אִי בִּמְפוּזָּרִין מַאי אִרְיָא מָקוֹם שֶׁהָרַבִּים מְצוּיִין שָׁם?', 'קושיא', 'אם הם מפוזרים – למה דווקא "מקום שהרבים מצויים שם"?', {'אי': 'אם', 'במפוזרין': 'במפוזרים', 'מאי אריא': 'למה דווקא', 'מצויין': 'נמצאים'}),
  ('אֲפִילּוּ אֵין הָרַבִּים מְצוּיִין שָׁם!', 'קושיא', 'גם במקום שאין בו הרבה אנשים – מעות מפוזרות שייכות למוצא!', {'מצויין': 'נמצאים'}),
  ('אֶלָּא לְעוֹלָם בִּצְרוּרִין,', 'תירוץ', 'אלא באמת מדובר במטבעות צרורים – קשורים יחד בצרור, שיש בהם סימן.', {'לעולם': 'באמת', 'בצרורין': 'קשורים יחד בצרור'}),
