# ---------- בנייה ובדיקה ----------
NQ = re.compile(r'[\u0591-\u05C7]')
def plain(x): return NQ.sub('', x)

def tokenize(text, gl):
    toks = text.split(' ')
    st = [strip(t) for t in toks]
    used = {}
    out = [None] * len(toks)
    for key in sorted(gl, key=lambda k: -len(k.split(' '))):
        kw = [strip(x) for x in key.split(' ')]; n = len(kw); found = False
        for i in range(len(toks) - n + 1):
            if st[i:i + n] == kw and all(out[j] is None for j in range(i, i + n)):
                out[i] = (n, gl[key])
                for j in range(i + 1, i + n): out[j] = 'skip'
                found = True
        if not found: raise SystemExit('gloss key not found: %r in %r' % (key, text))
    res, i = [], 0
    while i < len(toks):
        if out[i] is None: res.append({'t': toks[i]}); i += 1
        else:
            n, g = out[i]; res.append({'t': ' '.join(toks[i:i + n]), 'g': g}); i += n
    return res

def main():
    # 1) הטקסט המלא מכ"ג ע"ב קטע 3 עד סוף כ"ד ע"א
    full = ' '.join(SRC['gemara']['23b'][2:] + SRC['gemara']['24a'])
    mine = ' '.join(l[0] for u in U for l in u['lines'])
    norm = lambda s: re.sub(r'\s+', ' ', unicodedata.normalize('NFC', s)).strip()
    if norm(full) != norm(mine):
        a, b = norm(full), norm(mine)
        k = next(i for i in range(min(len(a), len(b))) if a[i] != b[i]) if a[:min(len(a), len(b))] != b[:min(len(a), len(b))] else min(len(a), len(b))
        raise SystemExit('TEXT MISMATCH at %d:\n sefaria: %s\n mine:    %s' % (k, a[k - 40:k + 60], b[k - 40:k + 60]))
    units, n = [], 0
    for u in U:
        lines = []
        for (t, role, ex, gl) in u['lines']:
            n += 1; lines.append({'n': len(lines) + 1, 'niqqud': t, 'role': role, 'explanation': ex, 'tokens': tokenize(t, gl)})
        assert all(len(m[1]) == 4 and len(set(m[1])) == 4 for m in u['mcq']), u['id']
        assert len({b for a_, b in u['flow']}) == len(u['flow']), u['id'] + ': duplicate order steps'
        assert len({a_ for a_, b in u['match']}) == len(u['match']) == len({b for a_, b in u['match']}), u['id'] + ': duplicate matching items'
        units.append({'id': u['id'], 'title': plain(u['title']), 'ic': u['ic'], 'daf': u['daf'], 'intro': u['intro'], 'lines': lines,
                      'flow': [{'type': a, 'text': b} for a, b in u['flow']],
                      'rashi': [{'dibur': a, 'text': b, 'kid': c} for a, b, c in u['rashi']],
                      'quiz': {'multiple_choice': [{'id': '%s_mc%d' % (u['id'], i + 1), 'question': q, 'options': o, 'correct': 0, 'explanation': e} for i, (q, o, e) in enumerate(u['mcq'])],
                               'true_false': [{'id': '%s_tf%d' % (u['id'], i + 1), 'statement': s, 'answer': a, 'explanation': e} for i, (s, a, e) in enumerate(u['tf'])],
                               'matching': {'id': u['id'] + '_match', 'title': 'מילה ← פירוש', 'pairs': [{'left': a, 'right': b} for a, b in u['match']]},
                               'order_the_steps': {'instruction': 'סדרו את שלבי הסוגיא לפי הסדר', 'correct_order': [b for a, b in u['flow']]},
                               'self_check': [{'prompt': u['self_check'][0], 'key_points': u['self_check'][1], 'model_answer': u['self_check'][2]}]}})
    # מילון: ניקוד המילה נלקח מתוך הטקסט (ספריא), לא מומצא
    gloss = []
    for uid, word, meaning, tip in GLOSS:
        u = next(x for x in units if x['id'] == uid)
        hit = None
        for l in u['lines']:
            for t in l['tokens']:
                for w in t['t'].split(' '):
                    if strip(w) == strip(word) and not hit: hit = (w, l['n'])
        if not hit: raise SystemExit('glossary word not in unit text: %s %s' % (uid, word))
        gloss.append({'aramaic': word, 'niqqud': re.sub(r'[.,:;!?–״׳"\']+$', '', hit[0]), 'meaning': plain(meaning), 'tip': tip, 'unit': uid, 'line': hit[1]})
    first, last = units[0]['lines'][0]['niqqud'], units[-1]['lines'][-1]['niqqud']
    out = {'title': 'חלק ב: המשך הגמרא', 'subtitle': 'דף כ"ג ע"ב (אחרי מחרוזות של דגים) וכל דף כ"ד ע"א',
           'range': {'from': 'בבא מציעא כ"ג ע"ב (Sefaria Bava_Metzia.23b:3)', 'to': 'בבא מציעא כ"ד ע"א, סוף העמוד (Bava_Metzia.24a:17)', 'opening': first, 'closing': last,
                     'continues_on': 'כ"ד ע"ב: ' + SRC['next_amud_first_segment_24b'][:60] + '…'},
           'source': SRC['source'], 'units': units, 'glossary': gloss, 'review': REVIEW,
           'stars_per_tab': 3, 'tabs': ['learn', 'quiz', 'match', 'order', 'self']}
    json.dump(out, open(os.path.join(ROOT, 'data/part_b.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    q = lambda k: sum(len(u['quiz'][k]) for u in units)
    print('units', len(units), 'lines', n, 'glossary', len(gloss), 'mcq', q('multiple_choice'), 'tf', q('true_false'),
          'match pairs', sum(len(u['quiz']['matching']['pairs']) for u in units), 'order steps', sum(len(u['flow']) for u in units), 'self', q('self_check'))
    print('opening:', first); print('closing:', last)

if __name__ == '__main__':
    main()
